<section id="tour-plan" class="section-padding"><div class="container"><div class="section-header"><span class="sub-title">Discover your route</span><h2>Your journey through Sri Lanka.</h2><p>Explore our tour plans and choose the route that suits your pace.</p></div>
<?php if(!tours()): ?><div class="empty-state"><h3>Let?s plan your Sri Lanka journey.</h3><p>Contact us for a personalised itinerary.</p><a href="#contact" class="btn-primary">Plan my trip</a></div><?php endif ?><div class="tour-selector" role="group" aria-label="Tour itineraries">
<?php foreach(tours() as $i=>$tour): ?><button type="button" class="tour-tab <?= $i===0?'selected':'' ?>" aria-pressed="<?= $i===0?'true':'false' ?>" data-tour="tour-<?= (int)$tour['id'] ?>"><?= e($tour['title']) ?></button><?php endforeach ?>
</div>
<?php foreach(tours() as $i=>$tour): ?><article class="tour-panel" id="tour-<?= (int)$tour['id'] ?>" <?= $i>0?'hidden':'' ?>><div class="tour-intro"><div><h3><?= e($tour['title']) ?></h3><p><?= e($tour['description']) ?></p><div class="tour-prices"><?php foreach(json_decode($tour['prices'],true) as $label=>$price): ?><div><span><?= e($label) ?></span><strong>$<?= number_format($price) ?></strong></div><?php endforeach ?></div><a class="btn-primary" href="#contact">Enquire about this tour</a></div><?php if(!empty($tour['poster'])): ?><a href="<?= e($tour['poster']) ?>" target="_blank" rel="noopener"><img src="<?= e($tour['poster']) ?>" alt="<?= e($tour['title']) ?> itinerary poster" loading="lazy"><span>View the full itinerary poster</span></a><?php endif ?></div>
<div class="day-grid"><?php foreach(json_decode($tour['days'],true) as $j=>$day): ?><details class="day-card" <?= $j===0?'open':'' ?>><summary><span>Day <?= $j+1 ?></span><h4><?= e($day['location']) ?></h4></summary><ul><?php foreach($day['activities'] as $activity): ?><li><?= e($activity) ?></li><?php endforeach ?></ul></details><?php endforeach ?></div></article><?php endforeach ?></div></section>
